function active$VoucherFilter$(sender) {
	var f = sender;
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	if (f._convection) f._convection = null;
	else changeLookupReadonly(f, 'ma_dvcs');
	&ReportSign.Filter.Active;
	f.setReferenceKeyFilter('tknh');
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
/* </flatten> */
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, x = f.getItemValue('mau_bc'), y = f.getItemValue('phan_loai'), q = f.getItemValue('chon_tt');
			var dFrom = f.getItem('tu_ngay').value, dTo = f.getItem('den_ngay').value, Account = f.getItem('tk').value;
			g._hiddenFields = [
				{Fields: 'ps_no_nt, ps_co_nt, ty_gia, ma_nt, du_tt_nt', Value: (x == '10')},
				{Fields: 'tk, tk_du', Value: (y == 3)}
			];
			g._hiddenForms = [
				{Form: [5, 6, 9, 10], Value: (y == '3') || (q != '1')&Circular.Script.ConditionHiddenForms;},
				{Form: [7, 8, 11, 12], Value: (y != '3') || (q != '1')&Circular.Script.ConditionHiddenForms;},
				{Form: [0, 1, 2, 3, 4], Value: (q != '1')&Circular.Script.ConditionHiddenForms;},
				{Form: [13, 14, 15, 16, 17], Value: (q == '1')}
			];

			g._alterTitle = [null, [['%s1', Account, true], ['%d1', dFrom, true], ['%d2', dTo, true]]];
			remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

